static inline void *nla_data(const struct nlattr *nla) /* <=== nla_data */ 
{
	return (char *) nla + NLA_HDRLEN;
}

static int tipc_add_tlv(struct sk_buff *skb, u16 type, void *data, u16 len) /* <=== tipc_add_tlv */ 
{
	struct tlv_desc *tlv = (struct tlv_desc *)skb_tail_pointer(skb);

	if (tipc_skb_tailroom(skb) < TLV_SPACE(len))
		return -EMSGSIZE;

	skb_put(skb, TLV_SPACE(len));
	tlv->tlv_type = htons(type);
	tlv->tlv_len = htons(TLV_LENGTH(len));
	if (len && data)
		memcpy(TLV_DATA(tlv), data, len);

	return 0;
}

static inline int nla_len(const struct nlattr *nla) /* <=== nla_len */ 
{
	return nla->nla_len - NLA_HDRLEN;
}

size_t nla_strlcpy(char *dst, const struct nlattr *nla, size_t dstsize) /* <=== nla_strlcpy */ 
{
	size_t srclen = nla_len(nla);
	char *src = nla_data(nla);

	if (srclen > 0 && src[srclen - 1] == '\0')
		srclen--;

	if (dstsize > 0) {
		size_t len = (srclen >= dstsize) ? dstsize - 1 : srclen;

		memset(dst, 0, dstsize);
		memcpy(dst, src, len);
	}

	return srclen;
}

typeDefs:
struct tipc_nl_compat_msg {
	u16 cmd;
	int rep_type;
	int rep_size;
	int req_type;
	struct net *net;
	struct sk_buff *rep;
	struct tlv_desc *req;
	struct sock *dst_sk;
}

struct tipc_link_info {
	__be32 dest;			/* network address of peer node */
	__be32 up;			/* 0=down, 1=up */
	char str[TIPC_MAX_LINK_NAME];	/* link name */
}

